use std::fs

trait Shape {
    fn name(self) -> string
    fn corners(self) -> int
    fn double_area(self) -> int
}

struct Item { label: string, c: int, d: int }

impl Shape for Item {
    fn name(self) -> string { self.label }
    fn corners(self) -> int { self.c }
    fn double_area(self) -> int { self.d }
}

fn num(s: string) -> int {
    s.parse::<int>().unwrap_or(0)
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut items: Vec<Item> = []
    for line in text.lines() {
        let p: Vec<string> = line.split_whitespace().collect()
        if p.len() < 2 { continue }
        let kind = p[0]
        if kind == "square" {
            let s = num(p[1])
            items.push(Item { label: kind, c: 4, d: 2 * s * s })
        } else if kind == "rect" && p.len() >= 3 {
            items.push(Item { label: kind, c: 4, d: 2 * num(p[1]) * num(p[2]) })
        } else if kind == "rtri" && p.len() >= 3 {
            items.push(Item { label: kind, c: 3, d: num(p[1]) * num(p[2]) })
        } else if kind == "trap" && p.len() >= 4 {
            items.push(Item { label: kind, c: 4, d: (num(p[1]) + num(p[2])) * num(p[3]) })
        }
    }
    let mut total = 0
    let mut best = -1
    let mut best_name = ""
    for it in items {
        println("${it.name()} corners=${it.corners()} area2=${it.double_area()}")
        total += it.double_area()
        if it.double_area() > best {
            best = it.double_area()
            best_name = it.name()
        }
    }
    println("total area2=${total}")
    if best < 0 {
        println("largest=none")
    } else {
        println("largest=${best_name} area2=${best}")
    }
}

